      "translation": "Ty • Ty",
      "explanation": "„euch” to zaimek drugiej osoby liczby mnogiej. Jest używane zarówno jako bezpośrednie uzupełnienie (gdzie?) - „ty”, jak i jako pośrednie uzupełnienie (do kogo?) - „do ciebie”.",
      "examples": [
        {
          "de": "Ich sehe euch.",
          "lv": "Widzę cię"
        },
        {
          "de": "Ich helfe euch.",
          "lv": "Pomogę ci"
        },
        {
          "de": "Ich gebe euch das Buch.",
          "lv": "Daję ci książkę"
        },
        {
          "de": "Ich danke euch.",
          "lv": "Dziękuję ci"
        },
        {
          "de": "Ihr erinnert euch.",
          "lv": "Pamiętasz"
        }
      ],
      "comparison": [
        {
          "word": "ihr",
          "meaning": "Ty",
          "example": "Ihr seid freundlich. = Jūs esat draudzīgi."
        },
        {
          "word": "euch",
          "meaning": "Ty/do ciebie",
          "example": "Ich helfe euch. = Es jums palīdzu."
        },
        {
          "word": "euer",
          "meaning": "Twój",
          "example": "Das ist euer Haus. = Tā ir jūsu māja."
        }
      ],
      "info": [
        "ihr = ty (podmiotowa forma zdania)",
        "euch = ty (gdzie? tworzysz) / ty (kogo? tworzysz)",
        "euer = twój (forma dzierżawcza)"
      ],
      "tip": {
        "text": "„euch” odpowiada na pytanie „komu?” lub jest bezpośrednim uzupełnieniem zdań z „ty”.",
        "example": "Pomogę ci. = Ich helfe euch. widzę cię = Ich sehe euch. Mówię ci. = Ich erzähle euch."
      },
      "accents": {
        "blue": [
          "ihr"
        ],
        "yellow": [
          "euch"
        ],
        "green": [
          "euer"
        ]
      }
