        "Ob używa się po słowach takich jak fragen, wissen, sehen, sagen, gdy nie ma bezpośredniego pytania.",
        "Ob zwykle nie jest używane w pytaniu bezpośrednim w języku niemieckim.",
        "Na poziomie A1 ważne jest rozróżnienie ob od oder."
