        "Pytaliśmy o ludzi, a nie o rzeczy czy zdarzenia.",
        "Rzeczy i zdarzenia zadawane są za pomocą was, a nie wer.",
        "Wer w języku niemieckim jest zwykle podmiotem zdania (mianownik) – Wer is das? = Co to jest?",
        "Kiedy pytamy, która z kilku osób, często używamy słowa wer z von (wer von euch = który z was).",
        "Wer zmienia formę w zależności od odmiany: wen (biernik), wem (celownik), wessen (dopełniacz) - to właśnie forma wer występuje najczęściej na poziomie A1."
